const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const fleets=[{name:'Crawler cranes',title:'Grounded in strength.',copy:'Built for demanding ground conditions and heavy, sustained lifts.',capacity:'250',boom:'Up to 90 m',application:'Heavy infrastructure'},{name:'Mobile cranes',title:'Agility without compromise.',copy:'Flexible mobilisation and precise positioning for fast-moving project sites.',capacity:'100',boom:'Up to 60 m',application:'Urban construction'},{name:'Tower cranes',title:'A higher perspective.',copy:'Vertical reach and controlled handling for the next generation of skylines.',capacity:'20',boom:'Up to 70 m jib',application:'High-rise construction'}];let activeFleet=0;function fleet(i){activeFleet=(i+3)%3;const f=fleets[activeFleet];if(window.updateFleetPhoto)window.updateFleetPhoto(activeFleet);$('#fleet-title').textContent=f.title;$('#fleet-copy').textContent=f.copy;$('#capacity').textContent=f.capacity;$('#boom').textContent=f.boom;$('#application').textContent=f.application;$('#fleet-count').textContent=`0${activeFleet+1} / 03`;$$('[data-fleet]').forEach((b,j)=>{b.setAttribute('aria-selected',j===activeFleet);b.tabIndex=j===activeFleet?0:-1})}$$('[data-fleet]').forEach(b=>{b.onclick=()=>fleet(+b.dataset.fleet);b.onkeydown=e=>{if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();fleet(e.key==='Home'?0:e.key==='End'?2:activeFleet+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1));$$('[data-fleet]')[activeFleet].focus()}}});$('#prev').onclick=()=>fleet(activeFleet-1);$('#next').onclick=()=>fleet(activeFleet+1);fleet(0);
const regions={west:[['Klang Valley','Central region','04 units available'],['Penang','Northern region','02 units available'],['Johor','Southern region','03 units available']],east:[['Kuching','Sarawak','02 units available'],['Bintulu','Sarawak','03 units available'],['Kota Kinabalu','Sabah','01 unit available']]};function region(r){$('#status-rows').innerHTML=regions[r].map(x=>`<div class="status-row"><span>${x[0]}</span><small>${x[1]}</small><span class="available">${x[2]}</span></div>`).join('');$$('[data-region]').forEach(b=>{b.classList.toggle('active',b.dataset.region===r);b.setAttribute('aria-pressed',b.dataset.region===r)})}$$('[data-region]').forEach(b=>b.onclick=()=>region(b.dataset.region));region('west');
const dialog=$('#details');let priorFocus;function open(content){priorFocus=document.activeElement;$('#dialog-content').innerHTML=content;dialog.showModal()}$('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>priorFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
$$('[data-specs]').forEach(b=>b.onclick=()=>{const f=fleets[activeFleet];open(`<div class="eyebrow muted">FLEET / 0${activeFleet+1}</div><h2>${f.name}</h2><p>${f.copy}</p><dl><dt>Capacity class</dt><dd>${f.capacity} tonnes</dd><dt>Maximum reach</dt><dd>${f.boom}</dd><dt>Application</dt><dd>${f.application}</dd></dl><p>Indicative concept specifications. Final capacity depends on the selected model, configuration, radius and load chart. Confirm equipment details with the planning team.</p><button class="button" id="download-spec">Download concept spec sheet ↓</button>`);$('#download-spec').onclick=()=>{const blob=new Blob([`TERAS — CONCEPT SPECIFICATION\n${f.name}\nCapacity class: ${f.capacity} tonnes\nBoom: ${f.boom}\nApplication: ${f.application}\n\nIllustrative specifications only. Not an operational load chart. Confirm with the equipment provider.`],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=f.name.replaceAll(' ','-')+'-concept.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
const scenarios=[{title:'Klang Valley infrastructure',text:'A planning scenario for urban infrastructure and rail works: constrained access, coordinated night lifting and precise placement of structural components.',needs:'Mobile crane mobilisation · Engineered lift planning · Site access coordination'},{title:'Penang port logistics',text:'A planning scenario for port expansion and heavy logistics: sustained lifting, equipment positioning and coordinated handling near active operations.',needs:'Crawler crane deployment · Heavy component handling · Phased mobilisation'}];$$('[data-project]').forEach(b=>b.onclick=()=>{const p=scenarios[+b.dataset.project];open(`<div class="eyebrow muted">PROJECT SCENARIO</div><h2>${p.title}</h2><p>${p.text}</p><p>${p.needs}</p><p>This is an illustrative use case, not a completed TERAS contract.</p>`)});
$$('[data-inquiry]').forEach(b=>b.onclick=()=>open(`<div class="eyebrow muted">LET’S PLAN YOUR NEXT LIFT</div><h2>Your project.<br>Our starting point.</h2><p>This concept is ready for a company WhatsApp number. Until it is connected, prepare and copy your enquiry below.</p><form id="enquiry"><label>Project location<input name="location" required placeholder="e.g. Shah Alam, Selangor" maxlength="150"></label><label>Equipment<select name="equipment"><option>Crawler crane</option><option>Mobile crane</option><option>Tower crane</option><option>Help me choose</option></select></label><label>Lift requirements<textarea name="requirements" required placeholder="Load weight, working height and preferred dates" maxlength="2000"></textarea></label><button class="button" type="submit">Copy enquiry ↗</button><p id="copy-status" role="status"></p></form>`));document.addEventListener('submit',async e=>{if(e.target.id!=='enquiry')return;e.preventDefault();const d=new FormData(e.target);const message=`Hello, I would like a crane quotation.\nProject: ${d.get('location')}\nEquipment: ${d.get('equipment')}\nRequirements: ${d.get('requirements')}`;try{await navigator.clipboard.writeText(message);$('#copy-status').textContent='Enquiry copied. Paste it into your preferred conversation.'}catch{const t=document.createElement('textarea');t.value=message;$('#copy-status').replaceChildren(t);t.select();$('#copy-status').prepend('Copy your enquiry below: ');}});
let bm=false;$('#language').onclick=()=>{bm=!bm;document.documentElement.lang=bm?'ms':'en';$$('[data-en]').forEach(e=>e.innerHTML=e.dataset[bm?'bm':'en']);$('#language').innerHTML=bm?'BM <span>/ EN</span>':'EN <span>/ BM</span>';$('#language').setAttribute('aria-label',bm?'Switch to English':'Switch to Bahasa Melayu')};
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
$('.fleet-card').id='fleet-panel'; document.querySelectorAll('[data-fleet]').forEach((b,i)=>{b.id='fleet-tab-'+i;b.setAttribute('aria-controls','fleet-panel')});
